// Define the object that will hold the broadcast (Cartesian) grid.
#[derive(Debug, Clone)]
pub struct BroadcastObject {
    // flattened storage of all (x[i], y[j]) pairs
    data: Vec<(f32, f32)>,
    // (number of rows, number of columns) == (x.len(), y.len())
    shape: (usize, usize),
}

impl BroadcastObject {
    /// Returns the shape of the grid as (rows, cols).
    pub fn shape(&self) -> (usize, usize) {
        self.shape
    }

    /// Returns the element at position (i, j), i < rows, j < cols.
    /// Panics if (i, j) is out of bounds.
    pub fn get(&self, i: usize, j: usize) -> (f32, f32) {
        let (rows, cols) = self.shape;
        assert!(
            i < rows && j < cols,
            "index out of bounds: requested ({}, {}), but shape is ({}, {})",
            i,
            j,
            rows,
            cols
        );
        // flatten 2D index into 1D
        self.data[i * cols + j]
    }
}

/// Constructs the broadcast grid (Cartesian product) of `x` and `y`.
/// The returned `BroadcastObject` will have shape `(x.len(), y.len())`,
/// and at position (i, j) holds `(x[i], y[j])`.
pub fn broadcast(x: Vec<f32>, y: Vec<f32>) -> BroadcastObject {
    let rows = x.len();
    let cols = y.len();
    // pre-allocate exactly rows*cols slots
    let mut data = Vec::with_capacity(rows * cols);

    // Fill in row-by-row
    for &xi in &x {
        for &yj in &y {
            data.push((xi, yj));
        }
    }

    BroadcastObject { data, shape: (rows, cols) }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn small_broadcast() {
        let x = vec![1.0_f32, 2.0];
        let y = vec![10.0_f32, 20.0, 30.0];
        let b = broadcast(x.clone(), y.clone());
        assert_eq!(b.shape(), (2, 3));

        let mut expected = Vec::new();
        for &xi in &x {
            for &yj in &y {
                expected.push((xi, yj));
            }
        }

        for i in 0..2 {
            for j in 0..3 {
                assert_eq!(b.get(i, j), expected[i * 3 + j]);
            }
        }
    }
}